import { ACTIONS, type ActionName } from "@/gen/actions";
import type { Action } from "@/gen/Action";
import { api } from "./api";
import { toast, toastError } from "@/components/Toast";

// The action list (crates/core/src/actions.rs, generated by gen-types): the same route, input and confirmation
// as the admin rules, the CLI and `launchpad do`.

export type { ActionName };
export type ActionParams = Record<string, string>;

export const action = (name: ActionName): Action => ACTIONS[name];

/** The action's route with its `{param}` segments filled, plus an optional query. */
export function actionPath(name: ActionName, params: ActionParams = {}, query?: Record<string, string>): string {
  const path = ACTIONS[name].route.replace(/\{(\w+)\}/g, (_, k: string) => {
    if (params[k] === undefined) throw new Error(`${name} needs ${k}`);
    return encodeURIComponent(params[k]);
  });
  const q = query ? new URLSearchParams(query).toString() : "";
  return q ? `${path}?${q}` : path;
}

/** The confirmation text with `{name}` filled from the params and vars; null when the action needs none. */
export function actionConfirm(name: ActionName, vars: Record<string, string> = {}): string | null {
  const text = ACTIONS[name].confirm;
  return text ? text.replace(/\{(\w+)\}/g, (m, k: string) => vars[k] ?? m) : null;
}

/** Actions that offer Undo in a toast after they ran: the undo action takes the same params. */
const UNDO: Partial<Record<ActionName, { done: string; undo: ActionName }>> = {
  "session.archive": { done: "Agent archived", undo: "session.unarchive" },
};

/** Runs an action: the same API call as its button, the CLI and a ready card. */
export function runAction<T = unknown>(name: ActionName, params: ActionParams = {}, body?: Record<string, unknown>, query?: Record<string, string>): Promise<T> {
  const undo = UNDO[name];
  const run = call<T>(name, params, body, query);
  if (!undo) return run;
  return run.then((r) => {
    toast(undo.done, { label: "Undo", run: () => void call(undo.undo, params).catch(toastError) });
    return r;
  });
}

function call<T>(name: ActionName, params: ActionParams, body?: Record<string, unknown>, query?: Record<string, string>): Promise<T> {
  const a = ACTIONS[name];
  const path = actionPath(name, params, query);
  const full = { ...(body ?? {}), ...(a.fixed ? JSON.parse(a.fixed) as Record<string, unknown> : {}) };
  switch (a.method) {
    case "DELETE": return api.delete<T>(path);
    case "PATCH": return api.patch<T>(path, full);
    case "PUT": return api.put<T>(path, full);
    default: return api.post<T>(path, full);
  }
}
